async function search(){const query=$('search').value.trim();if(!query){$('search-results').hidden=true;return;}const ticket=++searchTicket,result=$('search-results');result.hidden=false;result.replaceChildren(el('p',msg("research.searching")));await new Promise(r=>setTimeout(r,0));const books=content.books.map(b=>({book:b,entries:new Map(b.entries.map(e=>[e.ayah_id,e]))}));const hits=[];for(const a of content.ayahs){const fields=[{name:'قرآن',text:a.text_original},...books.map(b=>({name:b.book.title,text:b.entries.get(a.id)?.text||''}))];const hit=fields.find(f=>matches(f.text,query));if(hit)hits.push({ayah:a,hit});}if(ticket!==searchTicket)return;result.replaceChildren(el('p',msg("research.0_results_in_the_quran_rawwad_and", localizedNumber(hits.length)),'footnote'));const close=el('button',msg("research.close_results"));close.onclick=()=>result.hidden=true;result.append(close);for(const {ayah:a,hit}of hits.slice(0,100)){const b=el('button',undefined,'search-item');b.append(el('small',`${currentLabel(a)} · ${hit.name}`),el('p',(hit.text.length>280 ? hit.text.slice(0,280)+'…' : hit.text)));b.onclick=()=>{setSurah(a.surah_id,a.number);result.hidden=true;};result.append(b);}if(!hits.length)result.append(empty('نتیجه‌ای پیدا نشد.'));}
