async function init(){[content,catalog,noorManifest,offlineManifest]=await Promise.all([data('content.json'),data('research-data/catalog.json'),data('research-data/manifest.json'),data('offline/manifest.json')]);if(content.surahs.length!==114||content.ayahs.length!==6236)throw Error('شمارش متن قرآن معتبر نیست.');$('surah').replaceChildren(...content.surahs.map(s=>option(s.id,`${fa(s.id)} · ${s.name_ar}`)));$('translation').replaceChildren(...content.books.filter(b=>b.kind==='translation').map(b=>option(b.id,b.title)),...noorManifest.translationBooks.map(b=>option(`noor:${b.id}`,b.title)));if([...$('translation').options].some(o=>o.value===preferences.quranTranslation))$('translation').value=preferences.quranTranslation;if(!content.books.some(b=>b.kind==='translation'&&/^en(?:-|$)/i.test(b.language||''))&&!noorManifest.translationBooks.some(b=>/^en(?:-|$)/i.test(b.language||''))){const hint=el('small',msg('home.noEnglish'),'footnote');$('translation').closest('.card-top').after(hint);}const choices=[['moyassar','التفسير الميسر'],...Object.entries(offlineManifest.books)];$('tafsir-one').replaceChildren(...choices.map(([id,title])=>option(id,title)));$('tafsir-two').replaceChildren(option('',msg("research.no_comparison")),...choices.map(([id,title])=>option(id,title)));$('tafsir-one').value='317';$('tafsir-two').value='21';applyAppearance();
 $('juz-jump').replaceChildren(...Array.from({length:30},(_,i)=>option(i+1,localizedNumber(i+1))));
 for(const [id,field,label] of [['library-language','languages','همهٔ زبان‌ها'],['library-subject','subjects','همهٔ موضوع‌ها']]){$(id).replaceChildren(option('',authoredLabel(label)),...[...new Set(catalog.flatMap(b=>b[field]))].sort((a,b)=>a.localeCompare(b,'fa')).map(v=>option(v,(field==='languages' ? ({fa:'فارسی',ar:'عربی',en:'انگلیسی',ur:'اردو'}[v] || v) : v))));$(id).onchange=()=>{libraryLimit=36;renderLibrary()};}
 fullManifest=await data('full-books/manifest.json',true);if(fullManifest){for(const b of fullManifest.books)if(!catalog.some(c=>c.id===b.id))catalog.push({id:b.id,title:b.title,author:b.author,publisher:'',volumes:b.volumes.length,languages:[b.language||'ar'],subjects:[b.subject||''],availability:'text'});}packManager=createPackManager({load:data,fa,toast,openView:setView});packManager.refresh().catch(()=>{});if(fullManifest)bookReader=createBookReader({manifest:fullManifest,load:data,normalize,matches,openView:setView,copyText,toast});grammarReader=createGrammarReader({load:data,fa});wordReader=createWordReader({load:data,matches,fa,select:(s,v)=>{setSurah(s,v);setView('reader');readingPane?.revealResearch();document.querySelector('[data-tab=words]').click()},view:setView,toast});wordReader.init().catch(e=>toast(e.message));readingPane=createReadingPane({content,preferences,selected:()=>selected,translation:()=>$('translation').value,load:data,plain,select:setSurah,remember});setSurah(preferences.surah,preferences.verse);$('loading').hidden=true;notebook=createNotebook({host:$('notebook'),toast,download,legacyNotes:()=>personal.notes.map(n=>({...n,label:currentLabel(content.ayahs.find(a=>a.id===n.ayahId))}))});createExperience({openView:setView,copyText,download,toast});setView('home');document.body.dataset.ready='true';if(startupWarning)toast(startupWarning);}
$('nav').onclick=e=>{const b=e.target.closest('button[data-view]');if(b)setView(b.dataset.view);};
$('library-content').onchange=()=>{libraryLimit=36;renderLibrary()};$('library-sort').onchange=renderLibrary;$('library-reset').onclick=()=>{$('library-search').value='';$('library-language').value='';$('library-subject').value='';$('library-sort').value='default';libraryLimit=36;renderLibrary()};
