const folderButton=el('button',msg("research.bookmark_in_folder"));$('bookmark').after(folderButton);
const folderDialog=document.createElement('dialog');folderDialog.className='verse-dialog';uiAttr(folderDialog, 'aria-label', msg("research.bookmark_folder_alt"));uiMarkup(folderDialog, '<form><label>نام پوشه<input name="folder" required maxlength="60"></label><label>رنگ نشان<input name="color" type="color"></label><button>ثبت نشان</button><button name="cancel" type="button">انصراف</button></form>');document.body.append(folderDialog);
const folderForm=folderDialog.querySelector('form');folderForm.elements.cancel.onclick=()=>folderDialog.close();
folderButton.onclick=()=>{const old=bookmarkRows(personal,preferences.bookmarkFolders).find(r=>r.ayah===selected.id);folderForm.elements.folder.value=old?.folder||'عمومی';folderForm.elements.color.value=old?.color||'#93732b';folderDialog.showModal()};
folderForm.onsubmit=e=>{e.preventDefault();const folder=folderForm.elements.folder.value.trim();if(!folder)return;const rows=bookmarkRows(personal,preferences.bookmarkFolders),old=rows.find(r=>r.ayah===selected.id);const row={id:old?.id||'verse-'+selected.id,ayah:selected.id,folder,color:folderForm.elements.color.value};const next={...personal,bookmarks:[...new Set([...personal.bookmarks,selected.id])],bookmarkRows:old?rows.map(r=>r.id===old.id?row:r):[...rows,row]};if(persist(next)){folderDialog.close();uiText($('bookmark'), msg("research.bookmarked"));toast(msg("research.bookmark_saved_in_folder"))}};
$('bookmark').onclick=()=>{const rows=bookmarkRows(personal,preferences.bookmarkFolders),old=rows.find(r=>r.ayah===selected.id),updated=old?rows.filter(r=>r.id!==old.id):[...rows,{id:'verse-'+selected.id,ayah:selected.id,folder:'عمومی',color:'#93732b'}];const ids=[...new Set(updated.map(r=>r.ayah))];if(persist({...personal,bookmarks:ids,bookmarkRows:updated}))uiText($('bookmark'), (ids.includes(selected.id) ? msg("research.bookmarked") : msg("research.bookmark")));};
$('note-text').oninput=()=>{if(selected)drafts.set(selected.id,$('note-text').value)};
$('save-note').onclick=()=>{const text=$('note-text').value.trim();if(!text)return toast(msg("research.write_your_note_first"));if(text.length>100000)return toast(msg("research.note_is_too_long"));const old=personal.notes.find(n=>n.ayahId===selected.id);const note={id:old?.id||crypto.randomUUID(),ayahId:selected.id,text,updatedAt:new Date().toISOString()};if(persist({...personal,notes:[...personal.notes.filter(n=>n.id!==note.id),note]})){drafts.delete(selected.id);toast(msg("research.note_saved_for_this_verse"));}};
$('copy').onclick=async()=>{try{await copyText(`${selected.text_original}\n${$('translation-text').textContent}\n${currentLabel()} · ${$('translation').selectedOptions[0].textContent}\nمتن قرآن: Tanzil.net`);toast(msg("research.text_and_citation_copied"));}catch{toast(msg("research.automatic_copy_failed_select_the_text_and"));}};
let lastSelection='';document.addEventListener('selectionchange',()=>{const s=window.getSelection();if(s?.toString().trim())lastSelection=s.toString().trim();});$('word-search').onclick=()=>{if(!lastSelection)return toast(msg("research.select_a_word_or_phrase_first"));$('search').value=lastSelection;search();};
$('search-form').onsubmit=e=>{e.preventDefault();search().catch(e=>toast(e.message));};$('library-search').oninput=()=>{libraryLimit=36;renderLibrary();};$('more-books').onclick=()=>{libraryLimit+=36;renderLibrary();};$('notes-search').oninput=renderNotes;
$('export-notes').onclick=()=>download('mansour-research-backup.json',JSON.stringify({...personal,bookmarkRows:bookmarkRows(personal,preferences.bookmarkFolders),lastBatch:undefined},null,2),'application/json');
