$('import-notes').onclick=()=>$('import-file').click();$('import-file').onchange=async()=>{const file=$('import-file').files[0];try{if(!file)return;if(file.size>20_000_000)throw Error('فایل پشتیبان بیش از حد بزرگ است.');const incoming=validateBackup(JSON.parse(await file.text()));if(persist(mergeBackup(personal,incoming))){renderNotes();toast(msg("research.backup_merged_with_existing_notes"));}}catch(e){toast((e.message || msg("research.invalid_file")));}finally{$('import-file').value='';}};
$('mizan-volume').onchange=()=>loadMizanVolume().catch(e=>toast(e.message));$('mizan-page').onchange=renderMizanPage;for(const [id,d]of [['mizan-prev',-1],['mizan-next',1]])$(id).onclick=()=>{const s=$('mizan-page');s.selectedIndex=Math.min(s.options.length-1,Math.max(0,s.selectedIndex+d));renderMizanPage();};
